-- One POS: rehearse usp_ONEPOS_PostTransferRequest: Al Qusais (ERBQS) asks the counter store 5ALKD for 2 PCS of BAKED CROISSANT PLAIN
-- BUTTER 90GM (501477) and 1 PCS of BLACK FOREST CAKE (500048), posted as NaziaS (change @User to the branch's request approver's FACTS
-- username). Everything is rolled back at the end: no STR50 stays and its last number is unchanged. Run after creating the procedure.
DECLARE @User NVARCHAR(20) = N'NaziaS';
SELECT LASTNO_FYCODE, LASTNO_DOCTYPE, LASTNO_LASTNO AS last_before FROM dbo.LASTNO_MASTER WHERE LASTNO_DOCTYPE = 'STR50';
SET XACT_ABORT OFF;
BEGIN TRANSACTION;

EXEC dbo.usp_ONEPOS_PostTransferRequest @ClientID = @User, @BodyXML = N'<data><Transfer><DocDate>2026-10-26</DocDate><FromLocation>5ALKD</FromLocation><ToLocation>ERBQS</ToLocation>
  <Reference>One POS request REHEARSAL</Reference>
  <Line><ItemType>SMBK</ItemType><ItemCode>501477</ItemCode><ItemName>EB OUTLET - BAKED CROISSANT PLAIN BUTTER 90GM</ItemName><Qty>2</Qty><Unit>PCS</Unit></Line>
  <Line><ItemType>SMBK</ItemType><ItemCode>500048</ItemCode><ItemName>EB OUTLET - BLACK FOREST CAKE</ItemName><Qty>1</Qty><Unit>PCS</Unit></Line>
</Transfer></data>';

-- What it made (inside the transaction): the request, its lines, FACTS' approval record, allocation and log; no stock rows.
SELECT TSF_DOCNO, TSF_NARRATION, TSF_LOCATION_FM_DOCNO, TSF_LOCATION_TO_DOCNO, TSF_SMAN_DOCNO, TSF_DIVN_DOCNO, TSF_DEPT_DOCNO, TSF_TOTAL_QTY, TSF_POSTED_BY, TSF_POSTED_TS
FROM dbo.TRANSFER_HEADER WHERE TSF_DOCTYPE = 'STR50' AND TSF_NARRATION = N'One POS request REHEARSAL';
SELECT d.TSFDET_DOCSRNO, d.TSFDET_STOCK_DOCNO, d.TSFDET_QTY, d.TSFDET_UNIT_DOCNO, d.TSFDET_BATCH_DOCNO, d.TSFDET_AFTER_DOC_QTY FROM dbo.TRANSFER_DETAILS d
JOIN dbo.TRANSFER_HEADER h ON h.TSF_FYCODE = d.TSFDET_FYCODE AND h.TSF_DOCTYPE = d.TSFDET_DOCTYPE AND h.TSF_DOCNO = d.TSFDET_DOCNO WHERE h.TSF_DOCTYPE = 'STR50' AND h.TSF_NARRATION = N'One POS request REHEARSAL';
SELECT COUNT(*) AS stock_rows_should_be_0 FROM dbo.STOCK_TRANSACTION t
JOIN dbo.TRANSFER_HEADER h ON h.TSF_DOCTYPE = t.STTRN_DOCTYPE AND h.TSF_DOCNO = t.STTRN_DOCNO WHERE h.TSF_DOCTYPE = 'STR50' AND h.TSF_NARRATION = N'One POS request REHEARSAL';
SELECT a.ACTION_DOCNO, a.ACTION_KEY, a.ACTION_TYPE, a.ACTION_USER_DOCNO FROM dbo.ACTION_STATUS a
JOIN dbo.TRANSFER_HEADER h ON h.TSF_DOCTYPE = a.ACTION_DOCTYPE AND h.TSF_DOCNO = a.ACTION_DOCNO WHERE h.TSF_DOCTYPE = 'STR50' AND h.TSF_NARRATION = N'One POS request REHEARSAL';
SELECT COUNT(*) AS allocation_rows FROM dbo.DOCUMENT_ALLOCATION x
JOIN dbo.TRANSFER_HEADER h ON h.TSF_DOCTYPE = x.DA_DOCTYPE AND h.TSF_DOCNO = x.DA_DOCNO WHERE h.TSF_DOCTYPE = 'STR50' AND h.TSF_NARRATION = N'One POS request REHEARSAL';
SELECT l.AED_DOCNO, l.AED_STATUS, l.AED_USER_CODE FROM dbo.ADD_EDIT_DELETE_LOG l
JOIN dbo.TRANSFER_HEADER h ON h.TSF_DOCTYPE = l.AED_DOCTYPE AND h.TSF_DOCNO = l.AED_DOCNO WHERE h.TSF_DOCTYPE = 'STR50' AND h.TSF_NARRATION = N'One POS request REHEARSAL';

IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
SELECT LASTNO_FYCODE, LASTNO_DOCTYPE, LASTNO_LASTNO AS last_after_should_equal_before FROM dbo.LASTNO_MASTER WHERE LASTNO_DOCTYPE = 'STR50';
SELECT COUNT(*) AS left_after_rollback_should_be_0 FROM dbo.TRANSFER_HEADER WHERE TSF_DOCTYPE = 'STR50' AND TSF_NARRATION = N'One POS request REHEARSAL';
